# Supplementary Figure S4: pooled external validation (random effects) and multivariable Cox of the GIScore.
suppressPackageStartupMessages({library(data.table); library(ggplot2); library(patchwork)})
root <- "${PROJECT_ROOT}"; r4 <- file.path(root, "04_results/2026-10-12_Figure4_GALNT_run01"); out <- file.path(root, "05_figures/2026-10-12_Figure4_GALNT_run01"); fam <- "Arial"; bs <- 6.5
theme_pub <- function(bs = 6.5) theme_classic(base_size = bs, base_family = fam) + theme(axis.line = element_line(linewidth = 0.25), axis.ticks = element_line(linewidth = 0.25), plot.title = element_text(size = bs + 0.5, face = "bold"), plot.margin = margin(4, 4, 4, 4))
pfmt <- function(p) vapply(p, function(x) if (x < 0.001) formatC(x, format = "e", digits = 1) else formatC(x, format = "f", digits = if (x < 0.01) 4 else 3), "")
sm <- fread(file.path(r4, "validation_summary.csv")); pool <- fread(file.path(r4, "validation_pooled.csv"))
h <- sm[cohort != "TCGA-PAAD"]; h[, `:=`(lo = exp(logHR - 1.96 * se), hi = exp(logHR + 1.96 * se))]
hd <- rbind(data.table(lab = paste0(h$cohort, " (n=", h$n, ")"), HR = h$HR_high_vs_low, lo = h$lo, hi = h$hi, p = h$logrank_p, kind = "cohort"), data.table(lab = "Pooled (random effects)", HR = pool$pooled_HR, lo = pool$lo, hi = pool$hi, p = pool$p, kind = "pooled")); hd$lab <- factor(hd$lab, levels = rev(hd$lab)); hd$txt <- sprintf("%.2f (%.2f\u2013%.2f), p = %s", hd$HR, hd$lo, hd$hi, pfmt(hd$p))
pH <- ggplot(hd, aes(HR, lab)) + geom_vline(xintercept = 1, linewidth = 0.25, linetype = 2, colour = "grey50") + geom_errorbar(aes(xmin = lo, xmax = hi), width = 0, orientation = "y", linewidth = 0.35) + geom_point(aes(shape = kind, size = kind), fill = "#D9453B", colour = "black") + scale_shape_manual(values = c(cohort = 16, pooled = 23), guide = "none") + scale_size_manual(values = c(cohort = 1.6, pooled = 3), guide = "none") +
  geom_text(aes(x = 5.4, label = txt), hjust = 0, size = 5 / .pt, family = fam) + scale_x_log10(breaks = c(1, 2, 4)) + coord_cartesian(xlim = c(0.8, 5), clip = "off") + labs(x = "HR, GIScore-high vs low", y = NULL, title = "External validation (I\u00b2 = 3%)", tag = "A") + theme_pub() + theme(plot.margin = margin(4, 95, 4, 4))
mv <- rbind(fread(file.path(r4, "I_multivariable_cox_TCGA.csv"))[term == "risk_z"], fread(file.path(r4, "I_multivariable_cox_GSE62452.csv"))[term == "risk_z"], fill = TRUE); mv$lab <- c("TCGA: score alone", "TCGA: + age, sex, stage", "TCGA: + age, sex, stage, grade", "TCGA: + stroma/immune/acinar proxies", "GSE62452: + stage, grade"); mv$lab <- factor(mv$lab, levels = rev(mv$lab)); mv$txt <- sprintf("%.2f (%.2f\u2013%.2f), p = %s", mv$HR, mv$lo, mv$hi, pfmt(mv$p))
pI <- ggplot(mv, aes(HR, lab)) + geom_vline(xintercept = 1, linewidth = 0.25, linetype = 2, colour = "grey50") + geom_errorbar(aes(xmin = lo, xmax = hi), width = 0, orientation = "y", linewidth = 0.35) + geom_point(size = 1.6, colour = "#D9453B") + geom_text(aes(x = 2.6, label = txt), hjust = 0, size = 5 / .pt, family = fam) +
  scale_x_log10(breaks = c(1, 1.5, 2)) + coord_cartesian(xlim = c(0.9, 2.4), clip = "off") + labs(x = "HR per SD of GIScore (adjusted)", y = NULL, title = "Multivariable Cox", tag = "B") + theme_pub() + theme(plot.margin = margin(4, 95, 4, 4))
comp <- (pH / pI) + plot_layout(heights = c(1, 1.15)) & theme(plot.tag = element_text(face = "bold", size = 10, family = fam))
ggsave(file.path(out, "FigureS4_validation_multivariable.svg"), comp, width = 7.2, height = 4.2, device = svglite::svglite); ggsave(file.path(out, "FigureS4_validation_multivariable.png"), comp, width = 7.2, height = 4.2, dpi = 300, device = ragg::agg_png); cat("done\n")
